];

function rodarCaso(index) {
  if (index >= casos.length) {
    return;
  }

  const caso = casos[index];
  const body = {
    cliente: `Borda volume ${caso.volumes}`,
    peso_kg: 50.5,
    volumes: caso.volumes,
    uf_origem: 'SP',
    uf_destino: 'SP'
  };

  pm.sendRequest({
    url: `${pm.environment.get("url_base_v2")}/api/cotacoes`,
    method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify(body) }
  }, function (err, resV2) {
    if (err) { console.error("Erro:", err); return rodarCaso(index + 1); }

    const json = resV2.json();

    pm.test(`volumes ${caso.volumes} - desconto esperado (${caso.desconto_esperado})`, function () {
      pm.expect(json.desconto).to.eql(caso.desconto_esperado);
    });

    pm.test(`volumes ${caso.volumes} - valor_total esperado (${caso.valor_total_esperado})`, function () {
      pm.expect(json.valor_total).to.eql(caso.valor_total_esperado);
    });

    rodarCaso(index + 1);
  });
}

